#!/usr/bin/env node
/**
 * Codegen: snapshot the canonical `bank-ingest` skill files into a Worker
 * module so the `/api/me/bank-skill` download can zip them on the fly (the
 * Worker has no FS at runtime). Run before `wrangler dev` / `wrangler deploy`
 * — wired into the package.json `dev` and `deploy` scripts — so the served
 * bundle never drifts from the real skill on disk.
 *
 * Same pattern as scripts/gen-mcq-bundle.mjs. The `.env` is NOT bundled here;
 * the Worker bakes a per-admin `.env` at download time (BANK_API_BASE /
 * BANK_API_KEY / BANK_USER_EMAIL).
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SKILL = join(ROOT, '.claude', 'skills', 'bank-ingest');
const OUT = join(ROOT, 'worker', 'generated', 'bank-bundle.ts');

// Paths are relative to the skill root → they become the zip entry names.
const FILES = [
  'SKILL.md',
  'pyproject.toml',
  'scripts/api.py',
  'scripts/doctor.py',
  'scripts/parse_exam.py',
  'scripts/parse.py',
  'scripts/push.py',
  'scripts/tiptap.py',
];

const bundle = {};
for (const rel of FILES) {
  bundle[rel] = readFileSync(join(SKILL, rel), 'utf8');
}

const banner =
  '// AUTO-GENERATED by scripts/gen-bank-bundle.mjs — do not edit by hand.\n' +
  '// Source of truth: .claude/skills/bank-ingest/. Regenerated on dev/deploy.\n';

const body =
  banner +
  'export const BANK_BUNDLE: Record<string, string> = ' +
  JSON.stringify(bundle, null, 2) +
  ';\n';

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, body, 'utf8');
console.log(`gen-bank-bundle: wrote ${OUT} (${FILES.length} files)`);
